solution:
.scene {
  position: relative;
  height: 240px;
  margin: 16px;
}

.layer {
  position: absolute;
  width: 160px;
  height: 100px;
  padding: 8px;
  border: 1px solid #18181b;
  border-radius: 6px;
}

.a {
  top: 0;
  left: 0;
  z-index: 3;
  background: #fed7aa;
}

.group {
  position: relative;
  z-index: 1;
}

.b {
  top: 40px;
  left: 60px;
  z-index: 999;
  background: #bfdbfe;
}

/* ---- Solution ---- */
.group {
  z-index: auto; /* no stacking context: B now competes with A directly */
}
